-- Add new columns for knowledge classification and source tracing
ALTER TABLE public.knowledge_base ADD COLUMN IF NOT EXISTS access_level TEXT DEFAULT 'PUBLIC';
ALTER TABLE public.knowledge_base ADD COLUMN IF NOT EXISTS source_document TEXT;
ALTER TABLE public.knowledge_base ADD COLUMN IF NOT EXISTS source_page TEXT;

-- Create a unique constraint on title to allow deterministic upserts
-- Before adding constraint, ensure no duplicates exist by title
DELETE FROM public.knowledge_base a USING (
      SELECT MIN(id::text)::uuid as id, title
      FROM public.knowledge_base 
      GROUP BY title HAVING COUNT(*) > 1
   ) b
   WHERE a.title = b.title AND a.id <> b.id;

ALTER TABLE public.knowledge_base ADD CONSTRAINT knowledge_base_title_key UNIQUE (title);

-- UPSERT the 29 granular records + the existing Pricing Policy
