VALUES 
-- PUBLIC 
('Company Identity', 'company', 'RUSBORN OPC PRIVATE LIMITED. Brand: Rusborn (spoken "Rusborn"). Tagline: "Trust the Efforts, Rest is Born".', 'rusborn, tagline, company, name', 'PUBLIC', 100, 'Mentorship Sales Blueprint'),
('Contact Information', 'company', 'Email: support@rusborn.com, Website: rusborn.com, Phone: 9970019909', 'contact, email, phone, website', 'PUBLIC', 100, 'Mentorship Sales Blueprint'),
('Engineering Design and Product Development', 'engineering_services', 'RUSBORN provides engineering design and product-development support including: Mechanical design, Product design, Industrial design, CAD modeling, Engineering drawings, Technical documentation, Prototyping, Design optimization, Engineering design support.', 'engineering design, product development, mechanical design, CAD, prototyping', 'PUBLIC', 100, 'Mentorship Sales Blueprint'),
('CAD/CAE Training', 'cad_training', 'RUSBORN provides practical, industry-oriented technical training. Mentioned software includes: SolidWorks, CATIA, AutoCAD, ANSYS. Emphasis on CAD modeling, Engineering design, Simulation / CAE, Industry-oriented application, Practical skills rather than only clicking software buttons.', 'SolidWorks, CATIA, AutoCAD, ANSYS, CAD modeling, simulation', 'PUBLIC', 100, 'Mentorship Sales Blueprint'),
('Research and Project Support', 'student_mentorship', 'RUSBORN supports: Project and research topic selection, Final-year projects, Research planning, Technical project guidance, Analysis, Research development, Research paper development, Journal selection, Publication guidance, Research lifecycle mentoring. RUSBORN does NOT ghostwrite.', 'final-year projects, research support, publication guidance, paper development, ghostwrite', 'PUBLIC', 100, 'Mentorship Sales Blueprint'),
('Customized Technical Training', 'corporate_training', 'Customized training may target: Students, Professionals, Researchers, Faculty, Organizations. Training involves standards and industry practices such as: ISO, BIS, ASME, API / ASPI, ASTM, IS-related standards/practices.', 'technical training, students, professionals, ISO, BIS, ASME', 'PUBLIC', 100, 'Mentorship Sales Blueprint'),
('Fresher Training Solution', 'corporate_training', 'A comprehensive training program tailored for freshers bridging academic knowledge and workplace readiness. Focus: Skill building, Engagement, Career readiness, Technical skills, Soft skills (Communication, Teamwork, Problem solving), Mentorship, Continuous feedback, Performance assessment, Certification upon completion.', 'fresher training, skill building, soft skills, certification, readiness', 'PUBLIC', 100, 'Solving the Fresher Retention Challenge'),
('Corporate Program Implementation Phases', 'corporate_implementation', 'PHASE 1 - MONTH 1: Needs assessment, Training program design. PHASE 2 - MONTHS 2-3: Training delivery, Structured onboarding, Fresher skill development. PHASE 3 - MONTH 3+: Bond agreements, Formalized commitments, Reduction of turnover risk. PHASE 4 - MONTHS 4-24: Ongoing mentorship, Support, Retention tracking, Sustained results.', 'implementation phases, month 1, month 2, month 3, bond, mentorship', 'PUBLIC', 90, 'Solving the Fresher Retention Challenge'),
('Industry Drafting Standards Taught', 'cad_compliance', 'Industry standards taught include: ASME Y14.5 (American Society of Mechanical Engineers), ASPI / API (Petroleum and institutional standards), NFPA (National Fire Protection Association codes), ISO (International Organization for Standardisation), BIS (Bureau of Indian Standards), ARAI (Automotive Research Association of India).', 'ASME Y14.5, API, ASPI, NFPA, ISO, BIS, ARAI, standards', 'PUBLIC', 100, 'Mentorship Sales Blueprint'),
('Phase 2 Research Mentorship Structure', 'phase_2_research', 'Focus on navigating the academic machinery required to turn an idea into research that can meet journal expectations. RUSBORN does NOT ghostwrite. Student builds, owns, and defends the research. RUSBORN acts as Subject Mentor, Publication Strategist, and Guide. 20% Idea generation, 80% Execution (academic machinery).', 'research mentorship, ghostwrite, academic machinery, execution, defend', 'PUBLIC', 100, 'Mentorship Sales Blueprint'),
('8 Stages of Research Lifecycle', 'research_lifecycle', 'STAGE 1: Problem Scoping. STAGE 2: Subject and Area Selection. STAGE 3: Title Scoping. STAGE 4: Literature Review (Map landscape, identify gaps). STAGE 5: Methodology. STAGE 6: Results. STAGE 7: Conclusion and Discussion. STAGE 8: Citations (Proper referencing, formats).', 'research lifecycle, problem scoping, literature review, methodology, citations', 'PUBLIC', 100, 'Mentorship Sales Blueprint'),
('Journal Compliance and Desk Reject Shield', 'journal_compliance', 'Compliance may reduce avoidable desk-rejection risk. Journals may desk-reject papers before peer review if compliance requirements are not met. Areas include: File format, Title-page structure, Abstracts, Keywords, Highlights, Figures, Images, Artwork, Tables, Units, Classifications, Nomenclature, Data statements, Data-linking protocols, Supplementary materials, Co-submission protocols, Generative-AI compliance, Artwork compliance, Reference formatting.', 'journal compliance, desk reject, formatting, reference, abstract, AI compliance', 'PUBLIC', 100, 'Mentorship Sales Blueprint'),
('Pricing and Estimates', 'pricing_policy', 'RUSBORN requires a detailed discussion to determine accurate pricing, duration, and schedules. We do not provide standard course fees, discounts, or guarantees without consulting the team.', 'price, cost, fees, discount, guarantee, duration', 'PUBLIC', 100, NULL),

-- CLAIM
('Early Fresher Attrition Rates', 'fresher_retention', 'Up to 60% of freshers leave within their first 6 months. (According to RUSBORN material)', 'attrition, fresher, leave, turnover', 'CLAIM', 100, 'Solving the Fresher Retention Challenge'),
('Financial Cost of Fresher Turnover', 'corporate_roi', 'Cost per fresher lost within 6 months: 30-50% of annual salary. (According to RUSBORN material)', 'cost, lost, turnover, financial, salary', 'CLAIM', 100, 'Solving the Fresher Retention Challenge'),
('Retention Improvement through Training and Bond', 'fresher_retention', 'Without training and bond: approximately six-month average retention. With training and bond: one to two years retention (guaranteed per source). (According to RUSBORN material)', 'retention, bond, one to two years, guaranteed', 'CLAIM', 100, 'Solving the Fresher Retention Challenge'),
('Corporate Benefits of Retention Program', 'corporate_roi', 'Reduced hiring costs by up to 50% with longer fresher retention. Benefits include higher productivity, faster contribution, lower team disruption, better stability, stronger pipeline, long-term growth. (According to RUSBORN material)', 'benefits, hiring cost, 50% lower, productivity', 'CLAIM', 100, 'Solving the Fresher Retention Challenge'),
